# [tokio :: main] async fn main () { util :: bootstrap () ; let config = config :: get_config () . await ; let task_factory = Arc :: new (tasks :: TaskFactory :: new (config) . await) ; & task_factory . create_async_jobs () . await ; } pub struct TaskFactory { config : Arc < Mutex < Config > > , sched : Arc < JobScheduler > , job_map : HashMap < JobKey , Uuid > , } impl TaskFactory { pub async fn new (config : Arc < Mutex < Config > >) -> Self { TaskFactory { config , sched : Arc :: new (JobScheduler :: new () . await . unwrap ()) , job_map : HashMap :: new () , } } pub async fn create_async_jobs (& mut self) { let fs_job = Job :: new ("0 15 6,8,10 * Mar,Jun Fri 2017" , | _uuid , _lock | { let _ = Box :: new (async move { println ! ("{:?} Hi I ran" , chrono :: Utc :: now ()) ; }) ; }) . unwrap () ; let fs_id = self . sched . add (fs_job) . await ; self . job_map . insert (JobKey :: FsWatcher , fs_id . unwrap () . to_owned ()) ; tokio :: spawn (self . sched . start ()) ; } }